   724  /* Find the entry with the long names for the content of this archive.  */
   725  static const char *
   726  read_long_names (Elf *elf)
   727  {
   728    off_t offset = SARMAG;        /* This is the first entry.  */
   729    struct ar_hdr hdrm;
   730    struct ar_hdr *hdr;
   731    char *newp;
   732    size_t len;
   733
   734    while (1)
   735      {
   736        if (elf->map_address != NULL)
   737          {
   738            if ((size_t) offset > elf->maximum_size
   739                || elf->maximum_size - offset < sizeof (struct ar_hdr))
   740              return NULL;
   741
   742            /* The data is mapped.  */
   743            hdr = (struct ar_hdr *) (elf->map_address + offset);
   744          }
   745        else
   746          {
   747            /* Read the header from the file.  */
   748            if (unlikely (pread_retry (elf->fildes, &hdrm, sizeof (hdrm),
   749                                       elf->start_offset + offset)
   750                          != sizeof (hdrm)))
   751              return NULL;
   752
   753            hdr = &hdrm;
   754          }
   755
   756        /* The ar_size is given as a fixed size decimal string, right
   757           padded with spaces.  Make sure we read it properly even if
   758           there is no terminating space.  */
   759        char buf[sizeof (hdr->ar_size) + 1];
   760        const char *string = hdr->ar_size;
   761        if (hdr->ar_size[sizeof (hdr->ar_size) - 1] != ' ')
   762          {
   763            *((char *) mempcpy (buf, hdr->ar_size, sizeof (hdr->ar_size))) = '\0';
   764            string = buf;
   765          }
   766        len = atol (string);
   767
   768        if (memcmp (hdr->ar_name, "//              ", 16) == 0)
   769          break;
   770
   771        offset += sizeof (struct ar_hdr) + ((len + 1) & ~1l);
   772      }
   773
   774    /* Sanity check len early if we can.  */
   775    if (elf->map_address != NULL)
   776      {
   777        if (len > elf->maximum_size - offset - sizeof (struct ar_hdr))
   778          return NULL;
   779      }
   780
   781    /* Due to the stupid format of the long name table entry (which are not
   782       NUL terminted) we have to provide an appropriate representation anyhow.
   783       Therefore we always make a copy which has the appropriate form.  */
   784    newp = malloc (len);
   785    if (newp != NULL)
   786      {
   787        char *runp;
   788
   789        if (elf->map_address != NULL)
   790          {
   791            /* Simply copy it over.  */
   792            elf->state.ar.long_names = (char *) memcpy (newp,
   793                                                        elf->map_address + offset
   794                                                        + sizeof (struct ar_hdr),
   795                                                        len);
   796          }
   797        else
   798          {
   799            if (unlikely ((size_t) pread_retry (elf->fildes, newp, len,
   800                                                elf->start_offset + offset
   801                                                + sizeof (struct ar_hdr))
   802                          != len))
   803              {
   804                /* We were not able to read all data.  */
   805                free (newp);
   806                elf->state.ar.long_names = NULL;
   807                return NULL;
   808              }
   809            elf->state.ar.long_names = newp;
   810          }
   811
   812        elf->state.ar.long_names_len = len;
   813
   814        /* Now NUL-terminate the strings.  */
   815        runp = newp;
   816        while (1)
   817          {
   818            char *startp = runp;
   819            runp = (char *) memchr (runp, '/', newp + len - runp);
   820            if (runp == NULL)
   821              {
   822                /* This was the last entry.  Clear any left overs.  */
   823                memset (startp, '\0', newp + len - startp);
   824                break;
   825              }
   826
   827            /* NUL-terminate the string.  */
   828            *runp++ = '\0';
   829
   830            /* A sanity check.  Somebody might have generated invalid
   831               archive.  */
   832            if (runp >= newp + len)
   833              break;
   834          }
   835      }
   836
   837    return newp;
   838  }
