  1017     function must be called with the lock on the parent descriptor
  1018     being held. */
  1019  static Elf *
  1020  dup_elf (int fildes, Elf_Cmd cmd, Elf *ref)
  1021  {
  1022    struct Elf *result;
  1023
  1024    if (fildes == -1)
  1025      /* Allow the user to pass -1 as the file descriptor for the new file.  */
  1026      fildes = ref->fildes;
  1027    /* The file descriptor better should be the same.  If it was disconnected
  1028       already (using `elf_cntl') we do not test it.  */
  1029    else if (unlikely (ref->fildes != -1 && fildes != ref->fildes))
  1030      {
  1031        __libelf_seterrno (ELF_E_FD_MISMATCH);
  1032        return NULL;
  1033      }
  1034
  1035    /* The mode must allow reading.  I.e., a descriptor creating with a
  1036       command different then ELF_C_READ, ELF_C_WRITE and ELF_C_RDWR is
  1037       not allowed.  */
  1038    if (unlikely (ref->cmd != ELF_C_READ && ref->cmd != ELF_C_READ_MMAP
  1039                  && ref->cmd != ELF_C_WRITE && ref->cmd != ELF_C_WRITE_MMAP
  1040                  && ref->cmd != ELF_C_RDWR && ref->cmd != ELF_C_RDWR_MMAP
  1041                  && ref->cmd != ELF_C_READ_MMAP_PRIVATE))
  1042      {
  1043        __libelf_seterrno (ELF_E_INVALID_OP);
  1044        return NULL;
  1045      }
  1046
  1047    /* Now it is time to distinguish between reading normal files and
  1048       archives.  Normal files can easily be handled be incrementing the
  1049       reference counter and return the same descriptor.  */
  1050    if (ref->kind != ELF_K_AR)
  1051      {
  1052        ++ref->ref_count;
  1053        return ref;
  1054      }
  1055
  1056    /* This is an archive.  We must create a descriptor for the archive
  1057       member the internal pointer of the archive file descriptor is
  1058       pointing to.  First read the header of the next member if this
  1059       has not happened already.  */
