  1122  /* Return a descriptor for the file belonging to FILDES.  */
  1123  Elf *
  1124  elf_begin (int fildes, Elf_Cmd cmd, Elf *ref)
  1125  {
  1126    Elf *retval;
  1127
  1128    if (unlikely (__libelf_version != EV_CURRENT))
  1129      {
  1130        /* Version wasn't set so far.  */
  1131        __libelf_seterrno (ELF_E_NO_VERSION);
  1132        return NULL;
  1133      }
  1134
  1135    if (ref != NULL)
  1136      /* Make sure the descriptor is not suddenly going away.  */
  1137      rwlock_rdlock (ref->lock);
  1138    else if (unlikely (fcntl (fildes, F_GETFD) == -1 && errno == EBADF))
  1139      {
  1140        /* We cannot do anything productive without a file descriptor.  */
  1141        __libelf_seterrno (ELF_E_INVALID_FILE);
  1142        return NULL;
  1143      }
  1144
  1145    switch (cmd)
  1146      {
  1147      case ELF_C_NULL:
  1148        /* We simply return a NULL pointer.  */
  1149        retval = NULL;
  1150        break;
  1151
  1152      case ELF_C_READ_MMAP_PRIVATE:
  1153        /* If we have a reference it must also be opened this way.  */
  1154        if (unlikely (ref != NULL && ref->cmd != ELF_C_READ_MMAP_PRIVATE))
  1155          {
  1156            __libelf_seterrno (ELF_E_INVALID_CMD);
  1157            retval = NULL;
  1158            break;
  1159          }
  1160        FALLTHROUGH;
  1161
  1162      case ELF_C_READ:
  1163      case ELF_C_READ_MMAP:
  1164        if (ref != NULL)
  1165          retval = lock_dup_elf (fildes, cmd, ref);
  1166        else
  1167          /* Create descriptor for existing file.  */
  1168          retval = read_file (fildes, 0, ~((size_t) 0), cmd, NULL);
  1169        break;
  1170
  1171      case ELF_C_RDWR:
  1172      case ELF_C_RDWR_MMAP:
  1173        /* If we have a REF object it must also be opened using this
  1174           command.  */
  1175        if (ref != NULL)
  1176          {
  1177            if (unlikely (ref->cmd != ELF_C_RDWR && ref->cmd != ELF_C_RDWR_MMAP
  1178                          && ref->cmd != ELF_C_WRITE
  1179                          && ref->cmd != ELF_C_WRITE_MMAP))
  1180              {
  1181                /* This is not ok.  REF must also be opened for writing.  */
  1182                __libelf_seterrno (ELF_E_INVALID_CMD);
  1183                retval = NULL;
  1184              }
  1185            else
  1186              retval = lock_dup_elf (fildes, cmd, ref);
  1187          }
  1188        else
  1189          /* Create descriptor for existing file.  */
  1190          retval = read_file (fildes, 0, ~((size_t) 0), cmd, NULL);
  1191        break;
  1192
  1193      case ELF_C_WRITE:
  1194      case ELF_C_WRITE_MMAP:
  1195        /* We ignore REF and prepare a descriptor to write a new file.  */
  1196        retval = write_file (fildes, cmd);
  1197        break;
  1198
  1199      default:
  1200        __libelf_seterrno (ELF_E_INVALID_CMD);
  1201        retval = NULL;
  1202        break;
  1203      }
  1204
  1205    /* Release the lock.  */
  1206    if (ref != NULL)
  1207      rwlock_unlock (ref->lock);
  1208
  1209    return retval;
  1210  }
